import {Fluid} from './fluid.js';
import {AmbientAudio,instruments,soundscapes,progressions,parseChord,pitchForPosition,noteName} from './music.js';
const $=id=>document.getElementById(id);
const colors=[{name:'Lilac',hex:'#b7a0ff',rgb:[.50,.20,1]},{name:'Sea glass',hex:'#73e2d0',rgb:[.10,.86,.67]},{name:'Coral',hex:'#ff9e9e',rgb:[1,.19,.26]},{name:'Amber',hex:'#edca82',rgb:[1,.57,.12]}];
const state={selected:0,voices:[...soundscapes.stillwater.voices],progression:'daydream',custom:['Cmaj7','Am7','Fmaj7','G'],bpm:56,playing:false,elapsed:0,chordIndex:0};
const audio=new AmbientAudio();let busy=false,noteTimer;
$('voices').innerHTML=colors.map((c,i)=>`<div class="voice-row" style="--color:${c.hex}"><span class="voice-dot"></span><label for="voice${i}">${c.name}</label><select id="voice${i}" aria-label="${c.name} instrument">${Object.entries(instruments).map(([k,v])=>`<option value="${k}" ${state.voices[i]===k?'selected':''}>${v.name}</option>`).join('')}</select></div>`).join('');
const persisted=['soundscape','progression','chordLength','reverb','delay','volume','swirl','persistence','dropSize','rain','cycleColors','autoPour'];
function save(){try{localStorage.setItem('chromaflow-v1',JSON.stringify({settings:Object.fromEntries(persisted.map(id=>[id,$(id).type==='checkbox'?$(id).checked:$(id).value])),voices:state.voices,custom:state.custom,bpm:state.bpm}));}catch{}}
function restore(){try{const s=JSON.parse(localStorage.getItem('chromaflow-v1'));if(!s)return;for(const [id,value] of Object.entries(s.settings||{})){if(!persisted.includes(id))continue;const el=$(id);if(el.type==='checkbox')el.checked=!!value;else el.value=value;}if(s.voices?.length===4&&s.voices.every(v=>instruments[v]))state.voices=s.voices;if(s.custom?.length===4){s.custom.forEach(parseChord);state.custom=s.custom;$('chordInput').value=s.custom.join(', ');}state.bpm=Math.max(30,Math.min(100,Number(s.bpm)||56));if(!$('progression').value)$('progression').value='daydream';if(!$('soundscape').value)$('soundscape').value='stillwater';state.progression=$('progression').value;state.voices.forEach((v,i)=>$('voice'+i).value=v);}catch{}}
restore();
function activeChords(){return state.progression==='custom'?state.custom:progressions[state.progression];}
function renderChords(){const list=activeChords();$('chords').innerHTML=list.map((c,i)=>`${i?'<span class="chord-arrow" aria-hidden="true">→</span>':''}<button class="chord-chip ${i===state.chordIndex?'active':''}" data-chord="${i}" aria-label="Jump to ${c}" ${i===state.chordIndex?'aria-current="true"':''}>${c}<span class="progress"></span></button>`).join('');}
function selectColor(i){state.selected=i;paintCount=0;document.querySelectorAll('.color').forEach((el,j)=>{el.classList.toggle('selected',i===j);el.setAttribute('aria-pressed',i===j);});$('paletteHint').innerHTML=colors[i].name.toUpperCase()+` <span>· ${i+1}</span>`;$('cursor').style.borderColor=colors[i].hex+'80';}
document.querySelectorAll('.color').forEach(el=>el.addEventListener('click',()=>selectColor(Number(el.dataset.color))));
function loadFail(e){$('audioState').textContent=e.message||'Sound could not load. Try again.';$('audioState').style.color='#e5a0ac';}
async function togglePlay(){if(busy)return;if(state.playing){state.playing=false;audio.setPlaying(false);updateTransport();return;}busy=true;$('start').disabled=true;$('audioState').style.color='';$('audioState').textContent='Preparing your instruments…';try{await audio.initialize();await Promise.all(state.voices.map(v=>audio.load(v)));state.playing=true;audio.setPlaying(true);updateTransport();$('intro').classList.add('faded');drop(.4+Math.random()*.2,.5+Math.random()*.12,0);rainTimer=0;}catch(e){loadFail(e);}finally{busy=false;$('start').disabled=false;}}
function updateTransport(){$('start').querySelector('use').setAttribute('href',state.playing?'#pause':'#play');$('start').setAttribute('aria-label',state.playing?'Pause listening':'Begin listening');$('playLabel').textContent=state.playing?'In the flow':'Begin listening';$('audioState').textContent=state.playing?`${activeChords()[state.chordIndex]} · ${$('soundscape').selectedOptions[0].textContent}`:'Sound is waiting for you';$('sessionState').textContent=state.playing?'LISTEN. WANDER. REPEAT.':'YOUR MOMENT OF STILLNESS';document.querySelector('.transport').classList.toggle('paused',!state.playing);}
$('start').addEventListener('click',togglePlay);
function syncAudio(){audio.volume=Number($('volume').value)/100;audio.reverb=Number($('reverb').value)/100;audio.delay=Number($('delay').value)/100;audio.bpm=state.bpm;audio.update();}
function sliders(){for(const id of ['reverb','delay','volume','swirl','persistence','dropSize','rain']){const el=$(id);el.style.setProperty('--pct',((el.value-el.min)/(el.max-el.min)*100)+'%');if($(id+'Value'))$(id+'Value').textContent=id==='rain'?(el.value<28?'Occasional':el.value<60?'Unhurried':'Abundant'):el.value+'%';}}
$('soundscape').addEventListener('change',async()=>{const scape=soundscapes[$('soundscape').value];if(scape){state.voices=[...scape.voices];state.voices.forEach((v,i)=>$('voice'+i).value=v);$('reverb').value=scape.reverb;$('delay').value=scape.delay;$('scapeDescription').textContent=scape.text;sliders();syncAudio();if(audio.ctx){try{await Promise.all(state.voices.map(v=>audio.load(v)));}catch(e){loadFail(e);}}}else $('scapeDescription').textContent='Four colors. Four voices. Entirely your own.';save();updateTransport();});
for(let i=0;i<4;i++)$('voice'+i).addEventListener('change',async()=>{state.voices[i]=$('voice'+i).value;$('soundscape').value='custom';$('scapeDescription').textContent='Four colors. Four voices. Entirely your own.';save();if(audio.ctx)try{await audio.load(state.voices[i]);}catch(e){loadFail(e);}updateTransport();});
$('progression').addEventListener('change',()=>{state.progression=$('progression').value;state.elapsed=0;state.chordIndex=0;$('customChords').hidden=state.progression!=='custom';renderChords();updateTransport();save();});
$('applyChords').addEventListener('click',()=>{try{const c=$('chordInput').value.split(',').map(x=>x.trim());if(c.length!==4)throw new Error('Enter exactly four chords, separated by commas.');c.forEach(parseChord);state.custom=c;state.elapsed=0;state.chordIndex=0;$('chordError').textContent='Your progression is ready.';$('chordError').style.color='#b6e1c9';renderChords();updateTransport();save();}catch(e){$('chordError').textContent=e.message;$('chordError').style.color='#ffa6ab';}});
$('chords').addEventListener('click',e=>{const el=e.target.closest('[data-chord]');if(!el)return;state.chordIndex=Number(el.dataset.chord);state.elapsed=state.chordIndex*Number($('chordLength').value)*60/state.bpm;renderChords();updateTransport();if(state.playing)drop(.48,.55,state.selected);});
$('chordLength').addEventListener('change',()=>{state.elapsed=state.chordIndex*Number($('chordLength').value)*60/state.bpm;save();});
function setBpm(value){const previous=state.bpm;state.bpm=Math.max(30,Math.min(100,value));state.elapsed*=previous/state.bpm;$('bpmLabel').textContent=state.bpm;syncAudio();save();}
$('slower').onclick=()=>setBpm(state.bpm-2);$('faster').onclick=()=>setBpm(state.bpm+2);
for(const id of ['reverb','delay','volume','swirl','persistence','dropSize','rain'])$(id).addEventListener('input',()=>{sliders();syncAudio();sim.swirl=Number($('swirl').value)/100;sim.persistence=Number($('persistence').value)/100;save();});
for(const id of ['cycleColors','autoPour'])$(id).addEventListener('change',()=>{document.querySelector('.autopour').classList.toggle('off',!$('autoPour').checked);save();});
const tabs=['sound','fluid'];function switchTab(name){for(const tab of tabs){$(tab+'Panel').hidden=tab!==name;$(tab+'Tab').setAttribute('aria-selected',tab===name);$(tab+'Tab').tabIndex=tab===name?0:-1;}}for(const tab of tabs){$(tab+'Tab').onclick=()=>switchTab(tab);$(tab+'Tab').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const other=tabs.find(t=>t!==tab);switchTab(other);$(other+'Tab').focus();}});}
function togglePanel(){document.body.classList.toggle('panel-hidden');$('togglePanel').setAttribute('aria-expanded',!document.body.classList.contains('panel-hidden'));} $('togglePanel').onclick=togglePanel;
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else document.body.classList.toggle('zen');}catch{document.body.classList.toggle('zen');}};
function toggleZen(force){if(typeof force==='boolean')document.body.classList.toggle('zen',force);else document.body.classList.toggle('zen');$('zen').innerHTML=document.body.classList.contains('zen')?'Exit Zen <span>↙</span>':'Zen view <span>↗</span>';}
$('zen').onclick=()=>toggleZen();$('help').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=$('gotIt').onclick=()=>$('helpDialog').close();$('helpDialog').addEventListener('click',e=>{if(e.target===$('helpDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)||$('helpDialog').open)return;if(e.code==='Space'&&!e.repeat){e.preventDefault();togglePlay();}if(/^[1-4]$/.test(e.key))selectColor(Number(e.key)-1);if(e.key==='Escape')toggleZen(false);if(e.key==='Enter'&&document.activeElement===$('fluid')){e.preventDefault();drop(.3+Math.random()*.4,.35+Math.random()*.35,state.selected);}});
// Fluid rendering and the droplet/impact lifecycle.
const canvas=$('fluid'),ctx=canvas.getContext('2d',{alpha:false});const overlay=$('particles'),fx=overlay.getContext('2d');const stage=$('stage');
let width=1,height=1,dpr=1;const sim=new Fluid(window.innerWidth>720?224:144,window.innerWidth>720?156:112);const ink=document.createElement('canvas');ink.width=sim.w;ink.height=sim.h;const inkCtx=ink.getContext('2d');const pixels=inkCtx.createImageData(sim.w,sim.h);let drops=[],ripples=[],glows=[],lastFrame=0,rainTimer=0,paintTime=0,pointerDown=false,paintCount=0,previousPoint=null,frameCount=0;
const dust=Array.from({length:65},()=>({x:Math.random(),y:Math.random(),r:.4+Math.random()*.9,p:Math.random()*6}));
function resize(){const r=stage.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(window.devicePixelRatio||1,1.7);canvas.width=overlay.width=Math.round(width*dpr);canvas.height=overlay.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);fx.setTransform(dpr,0,0,dpr,0,0);}
new ResizeObserver(resize).observe(stage);
function seed(){sim.clear();for(let n=0;n<24;n++){const a=n/24*Math.PI*1.65;const x=.60+Math.cos(a)*(.13+n*.004),y=.55+Math.sin(a)*(.12+n*.005);const c=n<14?colors[0].rgb:colors[1].rgb;sim.splat(x,y,c,.035+n*.0003,Math.sin(a)*20,-Math.cos(a)*18);}for(let n=0;n<9;n++){const a=n/9*2;sim.splat(.74+Math.sin(a)*.10,.36+Math.cos(a)*.15,colors[2].rgb,.022,Math.cos(a)*8,-Math.sin(a)*8);}for(let n=0;n<24;n++)sim.step(1/30);}
function drop(x,y,color=state.selected,impulse=null){drops.push({x:Math.max(.04,Math.min(.96,x)),y:Math.max(.08,Math.min(.92,y)),color,life:0,duration:.45+Math.random()*.15,impulse:impulse||[Math.random()*14-7,13+Math.random()*12]});if(drops.length>45)drops.shift();}
function impact(d){const c=colors[d.color];const size=.018+Number($('dropSize').value)/100*.06;sim.splat(d.x,d.y,c.rgb,size,d.impulse[0],d.impulse[1]);ripples.push({x:d.x,y:d.y,color:c.hex,t:0});glows.push({x:d.x,y:d.y,color:c.hex,t:0});if(ripples.length>30)ripples.shift();if(glows.length>20)glows.shift();if(state.playing){const pitch=pitchForPosition(activeChords()[state.chordIndex],d.x,d.color);audio.note(state.voices[d.color],pitch).catch(loadFail);$('noteToast').textContent=`${noteName(pitch)}  ·  ${instruments[state.voices[d.color]].name.toUpperCase()}`;$('noteToast').classList.add('show');clearTimeout(noteTimer);noteTimer=setTimeout(()=>$('noteToast').classList.remove('show'),1400);}}
function position(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};}
function paint(e,force=false){const p=position(e);const now=performance.now();if(force||now-paintTime>160){const c=$('cycleColors').checked?(state.selected+Math.floor(paintCount++/3))%4:state.selected;const impulse=previousPoint?[Math.max(-65,Math.min(65,(p.x-previousPoint.x)*650)),Math.max(-65,Math.min(65,(p.y-previousPoint.y)*650))]:null;drop(p.x,p.y,c,impulse);previousPoint=p;paintTime=now;}}
canvas.addEventListener('pointerdown',e=>{pointerDown=true;previousPoint=null;canvas.setPointerCapture(e.pointerId);$('intro').classList.add('faded');paint(e,true);});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();$('cursor').style.left=(e.clientX-r.left)+'px';$('cursor').style.top=(e.clientY-r.top)+'px';if(e.pointerType!=='touch')$('cursor').style.display='block';if(pointerDown)paint(e);});
for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,()=>{pointerDown=false;previousPoint=null;});canvas.addEventListener('pointerleave',()=>$('cursor').style.display='none');
$('clear').onclick=()=>{sim.clear();drops=[];ripples=[];glows=[];};
$('bloom').onclick=()=>{for(let i=0;i<8;i++){const a=i/8*Math.PI*2;drop(.5+Math.cos(a)*.17,.5+Math.sin(a)*.17,i%4);}$('intro').classList.add('faded');};
function drawFluid(t){const p=pixels.data;for(let i=0;i<sim.n;i++){const k=i*4,r=sim.r[i],g=sim.g[i],b=sim.b[i],d=r+g+b;const grad=i>sim.w&&i<sim.n-sim.w?((sim.r[i+1]+sim.g[i+1]+sim.b[i+1])-(sim.r[i-1]+sim.g[i-1]+sim.b[i-1])):0;const highlight=Math.max(0,grad)*27;const lighting=.82+.18*Math.sin(i%sim.w*.035+Math.floor(i/sim.w)*.03+t*.12);p[k]=Math.min(255,7+233*(1-Math.exp(-r*1.7))*lighting+highlight);p[k+1]=Math.min(255,10+240*(1-Math.exp(-g*1.75))*lighting+highlight*.7);p[k+2]=Math.min(255,17+238*(1-Math.exp(-b*1.65))*lighting+highlight*.9);p[k+3]=255;}inkCtx.putImageData(pixels,0,0);ctx.fillStyle='#070b11';ctx.fillRect(0,0,width,height);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(ink,0,0,width,height);const vignette=ctx.createRadialGradient(width*.55,height*.5,height*.12,width*.5,height*.5,Math.max(width,height)*.72);vignette.addColorStop(0,'#070a1000');vignette.addColorStop(.62,'#070a1030');vignette.addColorStop(1,'#070a10d9');ctx.fillStyle=vignette;ctx.fillRect(0,0,width,height);}
function drawOverlay(dt,t){fx.clearRect(0,0,width,height);for(const p of dust){const x=(p.x+Math.sin(t*.035+p.p)*.006)*width,y=(p.y+Math.cos(t*.024+p.p)*.01)*height;fx.globalAlpha=.12+Math.sin(t*.5+p.p)*.07;fx.fillStyle='#d0c3f0';fx.beginPath();fx.arc(x,y,p.r,0,Math.PI*2);fx.fill();}fx.globalAlpha=1;for(let i=drops.length-1;i>=0;i--){const d=drops[i];d.life+=dt;const progress=Math.min(1,d.life/d.duration),x=d.x*width,y=d.y*height-(1-progress*progress)*105,c=colors[d.color].hex;const halo=fx.createRadialGradient(x,y,0,x,y,19);halo.addColorStop(0,c+'85');halo.addColorStop(.2,c+'40');halo.addColorStop(1,c+'00');fx.fillStyle=halo;fx.beginPath();fx.arc(x,y,19,0,Math.PI*2);fx.fill();fx.strokeStyle=c+'50';fx.lineWidth=1.2;fx.beginPath();fx.moveTo(x,y-12);fx.lineTo(x,y-2);fx.stroke();fx.fillStyle=c;fx.beginPath();fx.ellipse(x,y,2.3,3.5,0,0,Math.PI*2);fx.fill();fx.fillStyle='#fff9';fx.beginPath();fx.arc(x-.5,y-1,1,0,Math.PI*2);fx.fill();if(progress>=1){impact(d);drops.splice(i,1);}}
 fx.globalCompositeOperation='screen';for(let i=glows.length-1;i>=0;i--){const g=glows[i];g.t+=dt;const r=18+g.t*36,alpha=Math.max(0,1-g.t/1.7)*.15;fx.globalAlpha=alpha;const halo=fx.createRadialGradient(g.x*width,g.y*height,0,g.x*width,g.y*height,r);halo.addColorStop(0,g.color);halo.addColorStop(1,g.color+'00');fx.fillStyle=halo;fx.fillRect(g.x*width-r,g.y*height-r,r*2,r*2);if(g.t>1.7)glows.splice(i,1);}fx.globalAlpha=1;fx.globalCompositeOperation='source-over';for(let i=ripples.length-1;i>=0;i--){const r=ripples[i];r.t+=dt;const opacity=Math.max(0,1-r.t/2.1)*.30;fx.strokeStyle=r.color;fx.globalAlpha=opacity;fx.lineWidth=.65;fx.beginPath();fx.ellipse(r.x*width,r.y*height,5+r.t*39,2+r.t*15,0,0,Math.PI*2);fx.stroke();if(r.t>2.1)ripples.splice(i,1);}fx.globalAlpha=1;}
function tick(now){const dt=Math.min(.033,(now-lastFrame)/1000||.016);lastFrame=now;const t=now/1000;if(state.playing){state.elapsed+=dt;const length=Number($('chordLength').value)*60/state.bpm;const chord=Math.floor(state.elapsed/length)%4;if(chord!==state.chordIndex){state.chordIndex=chord;renderChords();updateTransport();}const line=$('chords').querySelector('.active .progress');if(line)line.style.width=(state.elapsed%length/length*100)+'%';}rainTimer+=dt;const interval=4.5-Number($('rain').value)/100*3.9;if($('autoPour').checked&&rainTimer>(state.playing?interval:interval*1.8)){rainTimer=0;const color=Math.floor(Math.random()*4);drop(.16+Math.random()*.71,.25+Math.random()*.53,color);}sim.step(dt);drawFluid(t);drawOverlay(dt,t);frameCount++;requestAnimationFrame(tick);}
sliders();syncAudio();$('bpmLabel').textContent=state.bpm;$('customChords').hidden=state.progression!=='custom';$('scapeDescription').textContent=soundscapes[$('soundscape').value]?.text||'Four colors. Four voices. Entirely your own.';document.querySelector('.autopour').classList.toggle('off',!$('autoPour').checked);sim.swirl=Number($('swirl').value)/100;sim.persistence=Number($('persistence').value)/100;renderChords();updateTransport();resize();seed();requestAnimationFrame(tick);
